import React,{Component} from "react";

export default class AddToDo extends Component{

    state = {
        Id:"",
        Title:"",
        Status:"Pending"
    };

    handleIdChange = (event) =>{
        console.log(event.target.value);
        this.setState({
            Id: event.target.value
        });
    };
    handleTitleChange = (event) =>{
        console.log(event.target.value);
        this.setState({
            Title: event.target.value
        });
    };
    handleStatusChange = (event) =>{
        console.log(event.target.value);
        this.setState({
            Status: event.target.value
        });
    };
    handleOnSubmit = (event) =>{
        console.log("Submit");
        event.preventDefault();
        this.props.OnAdd({
            Id:this.state.Id,
            Title:this.state.Title,
            Status:this.state.Status
        });
        this.setState({
            Id:"",
            Title:"",
            Status:"Pending"
        });
    };

    render(){
        return(
            <div>
                <h3> Add ToDo </h3>
                <form onSubmit={this.handleOnSubmit}>
                    <div className="form-group">
                        <input onChange={this.handleIdChange} className="form-control"  placeholder="Enter Id"/>
                    </div>
                    <div className="form-group">
                        <input onChange={this.handleTitleChange} className="form-control"  placeholder="Enter Title"/>
                    </div>
                    <div className="form-group">
                       <select onChange={this.handleStatusChange}  className="form-control">
                        <option value = "Done"> Done </option>
                        <option value = "Pending"> Pending </option>
                       </select>
                    </div>
                    <button type="submit" className="form-control btn btn-primary">Add ToDo</button>
                </form>
            </div>
        );
    }
}